96		private createServer(): http.Server {
97			return http.createServer(async (req, res) => {
98				this.trace(`Received request: ${req.method} ${req.url}`);
99	
100				if (req.method === 'OPTIONS') {
101					res.writeHead(200);
102					res.end();
103					return;
104				}
105	
106				// Handle /v1/messages endpoint (also //messages if base URL ends in /)
107				// Use URL to properly parse and extract pathname, ignoring query string
108				const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
109				if (req.method === 'POST' && (pathname === '/v1/messages' || pathname === '/messages' || pathname === '//messages')) {
110					await this.handleMessagesRequest(req, res);
111					return;
112				}
113	
114				if (req.method === 'GET' && req.url === '/') {
115					res.writeHead(200);
116					res.end('Hello from ClaudeLanguageModelServer');
117					return;
118				}
119	
120				this.sendErrorResponse(res, 404, 'not_found_error', 'Not found');
121			});
122		}
