125			try {
126				const body = await this.readRequestBody(req);
127				const auth = extractSessionId(req.headers, this.config.nonce);
128				if (!auth.valid) {
129					this.error('Invalid auth key');
130					this.sendErrorResponse(res, 401, 'authentication_error', 'Invalid authentication');
131					return;
132				}
133	
134				await this.handleAuthedMessagesRequest(body, req.headers, res, auth.sessionId);
135			} catch (error) {
136				this.sendErrorResponse(res, 500, 'api_error', error instanceof Error ? error.message : String(error));
137			}
138			return;
139		}
