302		 * Invokes the Claude Code session with a user request.
303		 * The prompt content is resolved internally from the request, and the
304		 * tool invocation token is taken from `request.toolInvocationToken`.
305		 * @param request The full chat request
306		 * @param stream Response stream for sending results back to VS Code
307		 * @param yieldRequested Function to check if the user has requested to interrupt
308		 * @param token Cancellation token for request cancellation
309		 */
310		public async invoke(
311			request: vscode.ChatRequest,
312			stream: vscode.ChatResponseStream,
313			yieldRequested: (() => boolean) | undefined,
314			token: vscode.CancellationToken
315		): Promise<void> {
316			if (this._store.isDisposed) {
317				throw new Error('Session disposed');
318			}
319	
320			if (token.isCancellationRequested) {
321				throw new CancellationError();
322			}
323	
324			const prompt = await resolvePromptToContentBlocks(request);
325			const toolInvocationToken = request.toolInvocationToken;
326	
327			this._cancelGatewayIdleTimer();
328	
329			// Check if settings files have changed since session started
330			if (this._queryGenerator && await this._settingsChangeTracker.hasChanges()) {
331				this.logService.trace('[ClaudeCodeSession] Settings files changed, restarting session with resume');
332				this._restartSession();
333			}
334	
335			// Check if the set of enabled tools has changed since the last request
336			if (this._queryGenerator && this._hasToolsChanged(request.tools)) {
337				this.logService.trace('[ClaudeCodeSession] Tools changed, restarting session with resume');
338				this._restartSession();
339			}
340			this._snapshotTools(request.tools);
341	
342			// Read current model and permission mode from session state service
343			// Do this BEFORE starting a session so the Options are correct from the start
344			const modelId = this.sessionStateService.getModelIdForSession(this.sessionId);
345			const permissionMode = this.sessionStateService.getPermissionModeForSession(this.sessionId);
346			const effortLevel = this.sessionStateService.getReasoningEffortForSession(this.sessionId);
347	
348			if (effortLevel !== this._currentEffort) {
349				this._currentEffort = effortLevel;
350				// Effort doesn't have a direct setter on the query generator, so we need to restart the session
351				if (this._queryGenerator) {
352					this._restartSession();
353				}
354			}
355			// Update model and permission mode on active session if they changed
356			if (modelId) {
357				await this._setModel(modelId);
358			}
359			await this._setPermissionMode(permissionMode);
360	
361			if (!this._queryGenerator) {
362				await this._startSession(token);
363			}
